          "names": {
            "KR": "주님 부활 대축일 파스카 성야",
            "VN": "Đêm Canh Thức Vượt Qua",
            "EN": "Easter Vigil in the Holy Night",
            "JP": "復活の聖なる徹夜祭",
            "LA": "Vigilia Paschalis in Nocte Sancta",
            "ZH": "復活節前夕守夜禮",
            "IT": "Veglia pasquale nella notte santa",
            "PT": "Vigília Pascal na Noite Santa",
            "ES": "Vigilia Pascual en la Noche Santa",
            "DE": "Die Feier der Osternacht"
          },
          "data": {
            "EN": {
              "prayer_offerings": {
                "text": "Accept, we ask, O Lord,\nthe prayers of your people\nwith the sacrificial offerings,\nthat what has begun in the paschal mysteries\nmay, by the working of your power,\nbring us to the healing of eternity.\nThrough Christ our Lord.",
                "lines": [
                  {
                    "sp": "",
                    "text": "Accept, we ask, O Lord,"
                  },
                  {
                    "sp": "",
                    "text": "the prayers of your people"
                  },
                  {
                    "sp": "",
                    "text": "with the sacrificial offerings,"
                  },
                  {
                    "sp": "",
                    "text": "that what has begun in the paschal mysteries"
                  },
                  {
                    "sp": "",
                    "text": "may, by the working of your power,"
                  },
                  {
                    "sp": "",
                    "text": "bring us to the healing of eternity."
                  },
                  {
                    "sp": "",
                    "text": "Through Christ our Lord."
                  }
                ]
              },
              "communion": {
                "text": "Christ our Passover has been sacrificed;\ntherefore let us keep the feast\nwith the unleavened bread of purity and truth, alleluia.",
                "lines": [
                  {
                    "sp": "",
                    "text": "Christ our Passover has been sacrificed;"
                  },
                  {
                    "sp": "",
                    "text": "therefore let us keep the feast"
                  },
                  {
                    "sp": "",
                    "text": "with the unleavened bread of purity and truth, alleluia."
                  }
                ]
              },
              "prayer_after": {
                "text": "Pour out on us, O Lord, the Spirit of your love,\nand in your kindness make those you have nourished\nby this paschal Sacrament\none in mind and heart.\nThrough Christ our Lord.",
                "lines": [
                  {
                    "sp": "",
                    "text": "Pour out on us, O Lord, the Spirit of your love,"
                  },
                  {
                    "sp": "",
                    "text": "and in your kindness make those you have nourished"
                  },
                  {
                    "sp": "",
                    "text": "by this paschal Sacrament"
                  },
                  {
                    "sp": "",
                    "text": "one in mind and heart."
                  },
                  {
                    "sp": "",
                    "text": "Through Christ our Lord."
                  }
                ]
              },
              "collect": {
                "text": "O God, who make this most sacred night radiant\nwith the glory of the Lord’s Resurrection,\nstir up in your Church a spirit of adoption,\nso that, renewed in body and mind,\nwe may render you undivided service.\nThrough our Lord Jesus Christ, your Son,\nwho lives and reigns with you in the unity of the Holy Spirit,\none God, for ever and ever.",
                "lines": [
                  {
                    "sp": "",
                    "text": "O God, who make this most sacred night radiant"
                  },
                  {
                    "sp": "",
                    "text": "with the glory of the Lord’s Resurrection,"
                  },
                  {
                    "sp": "",
                    "text": "stir up in your Church a spirit of adoption,"
                  },
                  {
                    "sp": "",
                    "text": "so that, renewed in body and mind,"
                  },
                  {
                    "sp": "",
                    "text": "we may render you undivided service."
                  },
                  {
                    "sp": "",
                    "text": "Through our Lord Jesus Christ, your Son,"
                  },
                  {
                    "sp": "",
                    "text": "who lives and reigns with you in the unity of the Holy Spirit,"
                  },
                  {
                    "sp": "",
                    "text": "one God, for ever and ever."
                  }
                ]
              }
            }
          },
