          "mergeDaily": true,
          "data": {
            "EN": {
              "entrance": {
                "text": "The love of God has been poured into our hearts through the Spirit of God dwelling within us, alleluia.",
                "lines": [
                  {
                    "sp": "",
                    "text": "The love of God has been poured into our hearts through the Spirit of God dwelling within us, alleluia."
                  }
                ]
              },
              "collect": {
                "text": "Almighty ever-living God, who willed the Paschal Mystery to be encompassed as a sign in fifty days, grant that from out of the scattered nations the confusion of many tongues may be gathered by heavenly grace into one great confession of your name. Through our Lord Jesus Christ, your Son, who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever.",
                "lines": [
                  {
                    "sp": "",
                    "text": "Almighty ever-living God, who willed the Paschal Mystery to be encompassed as a sign in fifty days, grant that from out of the scattered nations the confusion of many tongues may be gathered by heavenly grace into one great confession of your name. Through our Lord Jesus Christ, your Son, who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever."
                  }
                ]
              },
              "prayer_offerings": {
                "text": "Pour out upon these gifts the blessing of your Spirit, we pray, O Lord, so that through them your Church may be imbued with such love that the truth of your saving mystery may shine forth for the whole world. Through Christ our Lord.",
                "lines": [
                  {
                    "sp": "",
                    "text": "Pour out upon these gifts the blessing of your Spirit, we pray, O Lord, so that through them your Church may be imbued with such love that the truth of your saving mystery may shine forth for the whole world. Through Christ our Lord."
                  }
                ]
              },
              "communion": {
                "text": "On the last day of the festival, Jesus stood and cried out: If anyone is thirsty, let him come to me and drink, alleluia.",
                "lines": [
                  {
                    "sp": "",
                    "text": "On the last day of the festival, Jesus stood and cried out: If anyone is thirsty, let him come to me and drink, alleluia."
                  }
                ]
              },
              "prayer_after": {
                "text": "May these gifts we have consumed benefit us, O Lord, that we may always be aflame with the same Spirit, whom you wondrously poured out on your Apostles. Through Christ our Lord.",
                "lines": [
                  {
                    "sp": "",
                    "text": "May these gifts we have consumed benefit us, O Lord, that we may always be aflame with the same Spirit, whom you wondrously poured out on your Apostles. Through Christ our Lord."
                  }
                ]
              }
            }
          },
