          "riteData": {
            "LA": {
              "holy_saturday_rest": {
                "lines": [
                  {
                    "sp": "",
                    "text": "<1. Sabbato sancto Ecclesia ad sepulcrum Domini immoratur, passionem"
                  },
                  {
                    "sp": "",
                    "text": "eius et mortem, necnon ad inferos descensum meditans et"
                  },
                  {
                    "sp": "",
                    "text": "eius resurrectionem exspectans, in oratione et ieiunio."
                  },
                  {
                    "sp": "",
                    "text": "2. A sacrificio Missæ, sacra mensa denudata, Ecclesia abstinet,"
                  },
                  {
                    "sp": "",
                    "text": "usque dum, post sollemnem Vigiliam seu nocturnam resurrectionis"
                  },
                  {
                    "sp": "",
                    "text": "exspectationem, locus detur gaudiis paschalibus, quorum abundantia"
                  },
                  {
                    "sp": "",
                    "text": "in quinquaginta dies exundat."
                  },
                  {
                    "sp": "",
                    "text": "3. Sacra Communio hac die dari potest solummodo ad modum"
                  },
                  {
                    "sp": "",
                    "text": "viatici.>"
                  }
                ]
              }
            }
          },
